    val tips = listOf(
        ToolReferenceEntry("save", "STARTING OUT", "Keep more than one save", "You can save freely. Keep an earlier slot before difficult fights or major decisions so you can return if needed.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("training", "CHARACTER", "Spend learning points with trainers", "Levelling grants learning points. Find a trainer to turn them into stronger attributes or skills; training may also cost ore.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("danger", "EXPLORATION", "Leave dangerous areas for later", "Early on, avoid the orc territory and deep forests. Return after improving your character and equipment.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("journal", "QUESTS", "Check the quest journal", "The journal records active and resolved quests. Read it after conversations when you are unsure what to do next.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("knockout", "COMBAT", "Knocking someone out is not killing them", "Human enemies defeated in melee can survive unconscious. A finishing blow kills them and can provoke witnesses.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("golems", "ENEMY WEAKNESSES", "Prepare for Xardas's golems", "Bring a blunt weapon for the stone golem, fire magic for the ice golem, and ice or lightning magic for the fire golem.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_factions", "FACTIONS", "Keep a save before joining a camp", "Joining the Old Camp, New Camp or Brotherhood commits you to that route. Keep an earlier save if you want to try another faction.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_ore_trade", "TRADING", "Confirm both sides of a trade", "Gothic uses a barter window. Move the offered items and payment to the trade columns, then confirm the exchange.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_ranged", "COMBAT", "Pack the right ammunition", "Bows use arrows and crossbows use bolts. Both require dexterity to equip in the original Gothic. The relevant skill improves ranged accuracy.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_circles", "MAGIC", "Runes require magic-circle training", "A rune can be cast repeatedly, but you need the required circle and enough mana. Owning a rune is not the same as being trained to use it.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_scrolls", "MAGIC", "Keep scrolls for difficult encounters", "Scrolls let you use a spell without learning its rune circle, but still need mana and are consumed on use.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_harvest", "HUNTING", "Learn trophy skills before hunting", "Train the corresponding harvesting skill before collecting skins, claws or teeth. Learn to remove minecrawler warrior plates before hunting for armor materials.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_armor", "EQUIPMENT", "Compare each protection type", "Weapon protection, arrow protection, fire and magic defence are separate. A robe may be useful against magic even if another armor is stronger in melee.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_sleep", "RECOVERY", "Use safe beds between excursions", "Sleeping restores your resources and advances time. Use a bed you are allowed to use rather than provoking its owner.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_quest_items", "QUESTS", "Keep named and unusual items", "Do not sell named rings, lists, focus stones or story ingredients before checking the journal. Their uses may become clear later.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
        ToolReferenceEntry("g1_tip_weapon_training", "TRAINING", "Weapon skill matters as well as damage", "A stronger weapon helps, but training also improves your combat effectiveness. Build a reliable attack style instead of buying a weapon you cannot equip.", source = "https://www.worldofgothic.com/gothic/?go=g1faq"),
    )
    val items = listOf(
        ToolReferenceEntry("light", "SPELL SCROLLS", "Light scroll", "Costs 1 mana. Produces light for dark areas.", source = "https://www.worldofgothic.com/gothic/?go=g1spruchrollen"),
        ToolReferenceEntry("firebolt", "SPELL SCROLLS", "Firebolt scroll", "Costs 1 mana • 30 fire damage. A small fire spell.", source = "https://www.worldofgothic.com/gothic/?go=g1spruchrollen"),
        ToolReferenceEntry("telekinesis", "SPELL SCROLLS", "Telekinesis scroll", "Costs 1 mana per second, with a minimum cost of 10. Moves a targeted object from a distance.", source = "https://www.worldofgothic.com/gothic/?go=g1spruchrollen"),
        ToolReferenceEntry("rusty_sword", "ONE-HANDED WEAPONS", "Rusty Sword", "10 damage • 5 strength required. An early starter weapon. Replace it when your strength and ore allow.", source = "https://www.gothicz.net/gothic-1/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("short_sword", "ONE-HANDED WEAPONS", "Short Sword", "12 damage • 6 strength required. Buy from Fisk in chapter 1; compare it with your starting weapon.", source = "https://www.gothicz.net/gothic-1/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("longsword", "ONE-HANDED WEAPONS", "Longsword", "40 damage • 17 strength required. A stronger one-handed blade for a trained hero.", source = "https://www.gothicz.net/gothic-1/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("mace", "ONE-HANDED WEAPONS", "Mace", "23 damage • 10 strength required. A blunt weapon worth keeping for enemies such as stone golems.", source = "https://www.gothicz.net/gothic-1/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("g1_item_itmw_1h_sword_broad_01", "ONE-HANDED WEAPONS", "Broad Sword", "55 damage • 26 strength required. A mid-tier sword; check whether your strength already meets the requirement.", source = "https://www.gothicz.net/gothic-1/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("g1_item_itmw_1h_sword_03", "ONE-HANDED WEAPONS", "Guard's Sword", "32 damage • 12 strength required. Faction-style weapon. A better blade does not replace one-handed training.", source = "https://www.gothicz.net/gothic-1/predmety/jednorucni-zbrane/"),
        ToolReferenceEntry("g1_item_itmw_1h_sword_bastard_03", "ONE-HANDED WEAPONS", "Executioner", "65 damage • 33 strength required. A heavy one-handed blade for a strong hero.", source = "https://www.gothicz.net/gothic-1/predmety/jednorucni-zbrane/"),
