        ToolReferenceEntry("g1_item_itmw_2h_sword_heavy_01", "TWO-HANDED WEAPONS", "Heavy Two-hander", "86 damage • 64 strength required. A strength-focused weapon; check training before switching from one-handed combat.", source = "https://www.gothicz.net/gothic-1/predmety/obourucni-zbrane/"),
        ToolReferenceEntry("g1_item_lees_axt", "TWO-HANDED WEAPONS", "Lee's Axe", "105 damage • 95 strength required. Carried by Lee in the New Camp. It is not an ordinary early purchase.", source = "https://www.gothicz.net/gothic-1/predmety/obourucni-zbrane/"),
