        ToolReferenceEntry("g1_item_vlk_armor_m", "ARMOR", "Digger's Trousers", "Protection: weapons 15 • arrows 0 • fire 5 • magic 0. Buy from Fisk at the Old Camp marketplace; compare the cost with joining a camp for better equipment.", source = "https://www.gothicz.net/gothic-1/predmety/zbroje/"),
