        ToolReferenceEntry("g1_item_staerkering", "RINGS AND AMULETS", "Ring of Power", "+5 strength. Strength-boosting ring. Equip jewelry to receive its bonus; carrying it is not enough.", source = "https://www.gothicz.net/gothic-1/predmety/prsteny/"),
        ToolReferenceEntry("g1_item_staerkering2", "RINGS AND AMULETS", "Ring of Strength", "+10 strength. A stronger strength-boosting ring. Equip jewelry to receive its bonus; carrying it is not enough.", source = "https://www.gothicz.net/gothic-1/predmety/prsteny/"),
        ToolReferenceEntry("g1_item_ring_des_geschicks", "RINGS AND AMULETS", "Ring of Dexterity", "+5 dexterity. Dexterity-boosting ring useful to an archer. Equip jewelry to receive its bonus; carrying it is not enough.", source = "https://www.gothicz.net/gothic-1/predmety/prsteny/"),
        ToolReferenceEntry("g1_item_ring_der_magie", "RINGS AND AMULETS", "Ring of Magic", "+10 maximum mana. Increases your available mana when equipped. Equip jewelry to receive its bonus; carrying it is not enough.", source = "https://www.gothicz.net/gothic-1/predmety/prsteny/"),
        ToolReferenceEntry("g1_item_staerkeamulett", "RINGS AND AMULETS", "Amulet of Strength", "+10 strength. Strength-boosting amulet. Equip jewelry to receive its bonus; carrying it is not enough.", source = "https://www.gothicz.net/gothic-1/predmety/amulety/"),
        ToolReferenceEntry("g1_item_gewandtheitsamulett", "RINGS AND AMULETS", "Amulet of Agility", "+10 dexterity. Dexterity-boosting amulet. Equip jewelry to receive its bonus; carrying it is not enough.", source = "https://www.gothicz.net/gothic-1/predmety/amulety/"),
        ToolReferenceEntry("g1_item_neks_amulett", "RINGS AND AMULETS", "Nek's Amulet", "+5 weapon protection. Found with Nek outside the Old Camp. It is involved in Sly's missing-guard quest; keep it for that dialogue. Equip jewelry to receive its bonus; carrying it is not enough.", source = "https://www.gothicz.net/gothic-1/predmety/amulety/"),
        ToolReferenceEntry("g1_item_itfo_potion_haste_01", "POTIONS", "Potion of Swiftness", "Temporarily speeds up running. Useful for travelling and avoiding a fight.", source = "https://www.gothicz.net/gothic-1/predmety/lektvary/"),
