        ToolReferenceEntry("g1_item_meat", "FOOD", "Roasted Meat", "Restores health. Cook raw meat at a suitable fire or pan before using it as a travelling supply.", source = "https://www.gothicz.net/gothic-1/predmety/potraviny/"),
