        ToolReferenceEntry("g1_item_ore", "SUPPLIES", "Ore Nuggets", "The colony uses ore as its trading currency. Retain enough for armor, training and important supplies.", source = "https://www.gothicz.net/marvin/g1/insert-kody/predmety/ostatni/"),
        ToolReferenceEntry("g1_item_lockpick", "SUPPLIES", "Lockpicks", "Consumable tools for opening locked chests. Learning lockpicking reduces how many you break.", source = "https://www.gothicz.net/marvin/g1/insert-kody/predmety/ostatni/"),
