        ToolReferenceEntry("g1_item_itfo_plants_herb_01", "HERBS AND PLANTS", "Healing Herbs", "Restores 30 health. Collect wild plants while exploring. Gothic 1 plant effects should not be confused with their Gothic 2 counterparts.", source = "https://www.gothicz.net/gothic-1/predmety/herbar/"),
        ToolReferenceEntry("g1_item_itfo_plants_herb_02", "HERBS AND PLANTS", "Stronger Healing Herbs", "Restores 39 health. Collect wild plants while exploring. Gothic 1 plant effects should not be confused with their Gothic 2 counterparts.", source = "https://www.gothicz.net/gothic-1/predmety/herbar/"),
        ToolReferenceEntry("g1_item_itfo_plants_herb_03", "HERBS AND PLANTS", "Strongest Healing Herbs", "Restores 49 health. Collect wild plants while exploring. Gothic 1 plant effects should not be confused with their Gothic 2 counterparts.", source = "https://www.gothicz.net/gothic-1/predmety/herbar/"),
        ToolReferenceEntry("g1_item_itfo_plants_mushroom_02", "HERBS AND PLANTS", "Slave's Bread", "Restores 15 health. Collect wild plants while exploring. Gothic 1 plant effects should not be confused with their Gothic 2 counterparts.", source = "https://www.gothicz.net/gothic-1/predmety/herbar/"),
        ToolReferenceEntry("g1_item_itarscrollicecube", "SPELL SCROLLS", "Ice Block scroll", "Mana cost: 3. Temporarily freezes a susceptible target, giving you time to reposition. Consumed when cast.", source = "https://www.gothicz.net/gothic-1/predmety/magicke-svitky/"),
