        ToolReferenceEntry("g1_item_itarscrollshrink", "SPELL SCROLLS", "Shrink Monster scroll", "Mana cost: 5. Shrinks a susceptible creature, making a dangerous opponent easier to handle. Consumed when cast.", source = "https://www.gothicz.net/gothic-1/predmety/magicke-svitky/"),
        ToolReferenceEntry("g1_item_itarscrollsummondemon", "SPELL SCROLLS", "Summon Demon scroll", "Mana cost: 20. Calls a demon ally to fight for you; use care around friendly characters. Consumed when cast.", source = "https://www.gothicz.net/gothic-1/predmety/magicke-svitky/"),
