        ToolReferenceEntry("g1_item_itarscrolltrfwolf", "SPELL SCROLLS", "Transform into Wolf scroll", "Mana cost: 10. Changes the hero into a wolf. Nearby people may attack the transformed hero. Consumed when cast.", source = "https://www.gothicz.net/gothic-1/predmety/magicke-svitky/"),
